png","alt":null},{"src":"https://sidofqa.segob.gob.mx/imagenes_diarios/2025/10/23/MAT/sener_1_Cimg_105668.png","alt":null},{"src":"https://sidofqa.segob.gob.mx/imagenes_diarios/2025/10/23/MAT/sener_1_Cimg_106415.png","alt":null},{"src":"https://sidofqa.segob.gob.mx/imagenes_diarios/2025/10/23/MAT/sener_1_Cimg_107162.png","alt":null},{"src":"https://sidofqa.segob.gob.mx/imagenes_diarios/2025/10/23/MAT/sener_1_Cimg_107909.png","alt":null},{"src":"https://sidofqa.segob.gob.mx/imagenes_diarios/2025/10/23/MAT/sener_1_Cimg_112504.png","alt":null},{"src":"https://sidofqa.segob.gob.mx/imagenes_diarios/2025/10/23/MAT/sener_1_Cimg_113247.png","alt":null},{"src":"https://sidofqa.segob.gob.mx/imagenes_diarios/2025/10/23/MAT/sener_1_Cimg_121023.png","alt":null},{"src":"https://sidofqa.segob.gob.mx/imagenes_diarios/2025/10/23/MAT/sener_1_Cimg_121770.png","alt":null},{"src":"https://sidofqa.segob.gob.mx/imagenes_diarios/2025/10/23/MAT/sener_1_Cimg_122517.png","alt":null},{"src":"https://sidofqa.segob.gob.mx/imagenes_diarios/2025/10/23/MAT/sener_1_Cimg_123264.png","alt":null},{"src":"https://sidofqa.segob.gob.mx/imagenes_diarios/2025/10/23/MAT/sener_1_Cimg_124011.png","alt":null},{"src":"https://sidofqa.segob.gob.mx/imagenes_diarios/2025/10/23/MAT/sener_1_Cimg_124758.png","alt":null},{"src":"https://sidofqa.segob.gob.mx/imagenes_diarios/2025/10/23/MAT/sener_1_Cimg_127525.png","alt":null},{"src":"https://sidofqa.segob.gob.mx/imagenes_diarios/2025/10/23/MAT/sener_1_Cimg_128630.png","alt":null},{"src":"https://sidofqa.segob.gob.mx/imagenes_diarios/2025/10/23/MAT/sener_1_Cimg_129373.png","alt":null},{"src":"https://sidofqa.segob.gob.mx/imagenes_diarios/2025/10/23/MAT/sener_1_Cimg_130116.png","alt":null},{"src":"https://sidofqa.segob.gob.mx/imagenes_diarios/2025/10/23/MAT/sener_1_Cimg_130859.png","alt":null},{"src":"https://sidofqa.segob.gob.mx/imagenes_diarios/2025/10/23/MAT/sener_1_Cimg_131602.png","alt":null}]}}$payload$::jsonb; lid uuid;
BEGIN
 lid := (p->'ley'->>'id')::uuid;
 LOCK TABLE public.leyes,public.articulos,public.temas IN SHARE ROW EXCLUSIVE MODE;
 IF EXISTS(SELECT 1 FROM public.leyes WHERE id=lid OR lower(siglas)=lower(p->'ley'->>'siglas') OR lower(titulo)=lower(p->'ley'->>'titulo') OR url_original=p->'ley'->>'url_original') THEN RAISE EXCEPTION 'El instrumento ya existe: revisar, no reemplazar'; END IF;
 INSERT INTO public.leyes(id,titulo,siglas,fecha_publicacion,fecha_ultima_reforma,vigente,temas_clave,url_original,tipo) SELECT id,titulo,siglas,fecha_publicacion,fecha_ultima_reforma,vigente,temas_clave,url_original,tipo FROM jsonb_populate_record(null::public.leyes,p->'ley');
 INSERT INTO public.articulos(id,ley_id,identificador,contenido,tipo_articulo,titulo_nombre,capitulo_nombre,seccion_nombre,orden) SELECT id,ley_id,identificador,contenido,tipo_articulo,titulo_nombre,capitulo_nombre,seccion_nombre,orden FROM jsonb_populate_recordset(null::public.articulos,p->'articulos');
 INSERT INTO public.temas(ley_id,nivel,nombre,orden) SELECT lid,t->>'nivel',t->>'nombre',(t->>'orden')::int FROM jsonb_array_elements(p->'temas')t;
 IF (SELECT count(*)FROM public.articulos WHERE ley_id=lid)<>jsonb_array_length(p->'articulos') OR EXISTS(SELECT 1 FROM jsonb_array_elements(p->'articulos')b LEFT JOIN public.articulos a ON a.id=(b->>'id')::uuid WHERE a.id IS NULL OR (to_jsonb(a)-'fts'-'created_at') IS DISTINCT FROM b) THEN RAISE EXCEPTION 'Fallo de cotejo exacto de artículos'; END IF;
 IF (SELECT count(*)FROM public.temas WHERE ley_id=lid)<>jsonb_array_length(p->'temas') OR EXISTS(SELECT 1 FROM jsonb_array_elements(p->'temas')b WHERE NOT EXISTS(SELECT 1 FROM public.temas t WHERE ley_id=lid AND (to_jsonb(t)-'id'-'ley_id'-'created_at')=b)) THEN RAISE EXCEPTION 'Fallo de cotejo de estructura'; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.leyes l WHERE id=lid AND to_jsonb(l)-'created_at'=p->'ley') THEN RAISE EXCEPTION 'Metadatos diferentes'; END IF;
 IF EXISTS(SELECT 1 FROM public.articulos WHERE ley_id=lid AND (nullif(trim(contenido),'')IS NULL OR fts IS NULL OR fts=''::tsvector)) THEN RAISE EXCEPTION 'Texto o índice FTS vacío'; END IF;
END $ingest$;
COMMIT;
SELECT l.siglas,l.id,(SELECT count(*)FROM public.articulos a WHERE a.ley_id=l.id)fragmentos,(SELECT count(*)FROM public.temas t WHERE t.ley_id=l.id)temas FROM public.leyes l WHERE l.id='37c89350-82df-5021-8dbe-94e8e31e1d3e';
